/**                                                                                                                                                                                              
  * Builds GeoJSON chat location payload.                                                                                                                                                         
  * Stores marker data in msg._marker_data for the next step.                                                                                                                                     
  * Looks up marker_id from context at POST time for correct upsert.
  */
const geo = msg.metadata.geo;
const target = msg.metadata.target;
const source = msg.metadata.source;
const utils = global.get("utils");
const base_url = global.get("parat_bridge").base_urls.wasos;
const callsign = `${utils.build_callsign(source)} ${msg.entry.author}`;

const groupId = target.client_specific.room_id;
if (!groupId) {
    node.warn("No WaSOS room UUID available for geo operations");
    return null;
}

// Fresh lookup for marker_id (may have been stored since extraction)
const positions = global.get(
    `parat_bridge.connections.${msg.metadata.connection_name}.delhendelse_positions`
) || [];
const posEntry = positions.find(p => p.name === geo.name);

const geoFeature = {
    type: "Feature",
    properties: {
        objecttype: "chat",
        description: geo.name,
        color: "blue",
        username: callsign,
        groups: [groupId],
        id: callsign
    },
    geometry: {
        type: "Point",
        coordinates: [geo.lng, geo.lat]
    }
};

msg._marker_data = {
    base_url: base_url + "/api/geo/markers",
    marker_id: posEntry?.marker_id || null,
    connection_name: msg.metadata.connection_name,
    geo_name: geo.name,
    headers: {
        "x-api-key": target.api_key,
        "Content-Type": "application/json"
    },
    payload: {
        classification: "U",
        collaborative: false,
        color: "red",
        description: `[${source.client_system} - ${source.name}] ${geo.name}`,
        files: [],
        geometry: {
            type: "Point",
            coordinates: [geo.lng, geo.lat]
        },
        groups: [groupId],
        objectType: "marker"
    }
};

msg.url = base_url + "/api/chat/messages/"
    + target.client_specific.chatroom_name;
msg.headers = {
    "x-api-key": target.api_key,
    "Content-Type": "application/json"
};
msg.payload = {
    content: JSON.stringify(geoFeature),
    callsign: callsign,
    isLocation: true,
    replyMessageId: null,
    files: []
};

return msg;

/**
 * After GeoJSON chat POST completes, sets up the marker POST.
 * Uses /api/geo/markers/{uuid} for updates, /api/geo/markers for creation.                                                                                                                      
 */
const markerData = msg._marker_data;
if (!markerData) {
    node.warn("No marker data available");
    return null;
}

msg.url = markerData.marker_id
    ? markerData.base_url + "/" + markerData.marker_id
    : markerData.base_url;
msg.headers = markerData.headers;
msg.payload = markerData.payload;

return msg;

/**                                                                                                                                                                                              
 * Stores the marker UUID from the POST response                                                                                                                                                 
 * back into delhendelse_positions for future upserts.                                                                                                                                           
 */
const markerData = msg._marker_data;
if (!markerData) return msg;

const response = typeof msg.payload === "string"
    ? JSON.parse(msg.payload)
    : msg.payload;

const uuid = response?.uuid;
if (uuid && markerData.connection_name && markerData.geo_name) {
    const key = `parat_bridge.connections.${markerData.connection_name}.delhendelse_positions`;
    const positions = global.get(key) || [];
    const entry = positions.find(p => p.name === markerData.geo_name);
    if (entry) {
        entry.marker_id = uuid;
        global.set(key, positions);
    }
}

delete msg._marker_data;
return msg;
